      "card_ids": ["C31","C33"]
    },
    {
      "claim": "The physicochemical prior is uncertain and not endpoint proof; zwitterionic fluoroquinolones with low logD can still be well absorbed, so the prior does not affirmatively establish F < 20%.",
      "card_ids": ["C04","C13","C14"]
    }
  ],
  "new_evidence_assessment": [
